<?php require 'config.php'; if($_SERVER['REQUEST_METHOD']!=='POST') exit('Invalid request'); check_csrf(); $title=trim($_POST['title']??'');$desc=trim($_POST['description']??'');$cat=trim($_POST['category']??'Product');$name=trim($_POST['name']??'');$email=trim($_POST['email']??''); if(!$title||!$desc||!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)){flash('Please complete all required fields.','bad');header('Location:index.php#submit');exit;} $slug=strtolower(trim(preg_replace('/[^A-Za-z0-9]+/','-', $title),'-'));$base=$slug;$i=1;while(true){$q=db()->prepare('SELECT id FROM features WHERE slug=?');$q->execute([$slug]);if(!$q->fetch())break;$slug=$base.'-'.$i++;}$s=db()->prepare('INSERT INTO features(title,slug,description,category,author_name,author_email) VALUES(?,?,?,?,?,?)');$s->execute([$title,$slug,$desc,$cat,$name,$email]);flash('Your feature request is live on the board.');header('Location:feature.php?slug='.urlencode($slug));
